import pytest
from hypothesis import given
import hypothesis.strategies as st

from solution import filter_integers


def reference(values):
    # Obviously-correct model: keep integers but NOT booleans,
    # since True/False are not "integers" conceptually even though
    # isinstance(True, int) is True in Python.
    return [x for x in values if isinstance(x, int) and not isinstance(x, bool)]


# ---- concrete examples from the spec docstring ----

def test_example_1():
    assert filter_integers(['a', 3.14, 5]) == [5]


def test_example_2():
    assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]


# ---- scalar / boundary behaviour ----

def test_empty_list_returns_empty():
    assert filter_integers([]) == []


def test_no_integers_returns_empty():
    assert filter_integers(['a', 3.14, {}, [], None, 'abc', 2.0]) == []


def test_all_integers_preserved():
    assert filter_integers([1, 2, 3]) == [1, 2, 3]


def test_negative_zero_and_large_integers():
    vals = [-10**100, -1, 0, 1, 10**100]
    assert filter_integers(vals) == vals


def test_floats_excluded_even_when_integral():
    assert filter_integers([5.0, -0.0, 1.0, 2, 3]) == [2, 3]


def test_strings_excluded():
    assert filter_integers(["1", "2", 1, 2]) == [1, 2]


def test_none_excluded():
    assert filter_integers([None, 0, None, 1]) == [0, 1]


def test_containers_excluded():
    assert filter_integers([{}, [], (), set(), {"a": 1}, [1], (2,), 4]) == [4]


def test_booleans_excluded():
    # True/False are instances of int but are not integers per spec.
    assert filter_integers([True, False, 1, 0, 2]) == [1, 0, 2]


def test_booleans_only_returns_empty():
    assert filter_integers([True, False]) == []


def test_mixed_bool_int_distinction():
    # 1 == True and 0 == False in Python, but filtering must be by type.
    result = filter_integers([True, 1])
    assert result == [1]
    assert len(result) == 1
    assert type(result[0]) is int


def test_returns_list_type():
    result = filter_integers([1, 'a', 2.5])
    assert type(result) is list


def test_result_elements_are_exact_int_not_bool():
    result = filter_integers([1, True, 2, False, 3.14, "x"])
    for x in result:
        assert type(x) is int


def test_order_preserved():
    vals = [3, 'a', 1, 2.5, 2, {}, 1]
    assert filter_integers(vals) == [3, 1, 2, 1]


def test_does_not_mutate_input():
    vals = [1, 'a', 2.5, 3, True, None]
    snapshot = list(vals)
    filter_integers(vals)
    assert vals == snapshot


def test_returns_new_list_object():
    vals = [1, 2, 3]
    result = filter_integers(vals)
    assert result == vals
    assert result is not vals


# ---- property-based tests ----

_any_scalar = st.one_of(
    st.integers(min_value=-10**18, max_value=10**18),
    st.booleans(),
    st.floats(allow_nan=False, allow_infinity=False, width=32),
    st.text(max_size=5),
    st.none(),
    st.just(0.0),
    st.just(5.0),
)

_any_value = st.one_of(
    _any_scalar,
    st.lists(_any_scalar, max_size=3),
    st.dictionaries(st.text(max_size=3), _any_scalar, max_size=2),
    st.tuples(_any_scalar, _any_scalar),
)


@given(st.lists(_any_value, max_size=20))
def test_equivalence_to_reference_model(vals):
    assert filter_integers(vals) == reference(vals)


@given(st.lists(_any_value, max_size=20))
def test_result_contains_only_non_bool_ints(vals):
    result = filter_integers(vals)
    assert isinstance(result, list)
    for x in result:
        assert isinstance(x, int)
        assert not isinstance(x, bool)


@given(st.lists(_any_value, max_size=20))
def test_result_is_subsequence_preserving_order(vals):
    result = filter_integers(vals)
    # every result element must appear in order in the input
    idx = 0
    for v in vals:
        if idx < len(result) and v is result[idx] or (idx < len(result) and type(v) is int and v == result[idx] and type(v) == type(result[idx])):
            # need careful walk: advance when types match exactly
            pass
        else:
            continue
    # simpler robust check: reference equality of filtered sequence
    assert result == reference(vals)
    # order check: indices strictly increasing
    positions = []
    start = 0
    for r in result:
        found = None
        for i in range(start, len(vals)):
            if type(vals[i]) is int and vals[i] == r and type(vals[i]) == type(r):
                # type is int covers value equality; bool already excluded
                found = i
                break
            if isinstance(vals[i], int) and not isinstance(vals[i], bool) and vals[i] == r:
                found = i
                break
        assert found is not None
        positions.append(found)
        start = found + 1
    assert positions == sorted(positions)


@given(st.lists(_any_value, max_size=20))
def test_idempotence(vals):
    once = filter_integers(vals)
    assert filter_integers(once) == once


@given(st.lists(st.integers(min_value=-1000, max_value=1000), max_size=20))
def test_all_int_list_is_identity(vals):
    assert filter_integers(vals) == vals


@given(st.lists(st.one_of(st.text(max_size=5), st.floats(allow_nan=False, allow_infinity=False), st.none()), max_size=20))
def test_no_int_input_gives_empty(vals):
    # strategies above never produce non-bool ints
    assume_vals = [v for v in vals if not (isinstance(v, int) and not isinstance(v, bool))]
    assert filter_integers(assume_vals) == []
